    [TestMethod]
    [DataRow("Hello World", "hello-world")]
    [DataRow("  Spaces Around  ", "spaces-around")]
    [DataRow("Multiple   Spaces", "multiple-spaces")]
    [DataRow("Special!@#Characters", "special-characters")]
    [DataRow("already-a-slug", "already-a-slug")]
    public void GenerateSlug_VariousInputs_ReturnsExpectedSlug(string title, string expected)
    {
        var result = _formatter.GenerateSlug(title);

        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    public void GenerateSlug_Result_IsLowerCase()
    {
        var result = _formatter.GenerateSlug("UPPER CASE TITLE");

        Assert.MatchesRegex(@"^[a-z0-9\-]+$", result);
    }

    [TestMethod]
    public void GenerateSlug_Result_DoesNotStartOrEndWithDash()
    {
        var result = _formatter.GenerateSlug("--trimmed--");

        Assert.IsFalse(result.StartsWith('-'));
        Assert.IsFalse(result.EndsWith('-'));
    }

